// ─── File: src/main/java/com/bank/overview/service/TransferService.java ───
package com.bank.overview.service;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

public class TransferService {
    private final List<String> log = new ArrayList<>();

    // ALL 5 KEYWORDS demonstrated:
    public String transfer(String from, String to, BigDecimal amount)
        throws Exception {          // THROWS: declares possible exception

        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
            // THROW: raises exception
        }

        // TRY: code that might fail
        try {
            log.add("TRY: debit " + from);
            if ("FROZEN".equals(from)) throw new RuntimeException("Account frozen!");
            log.add("TRY: credit " + to);
            if ("INVALID".equals(to)) throw new RuntimeException("Invalid account!");
            return "Transfer Rs." + amount + " from " + from + " to " + to;

        // CATCH: handle exception
        } catch (RuntimeException e) {
            log.add("CATCH: " + e.getMessage());
            throw e;  // re-throw after logging

        // FINALLY: always runs
        } finally {
            log.add("FINALLY: cleanup");
        }
    }

    public List<String> getLog() { return List.copyOf(log); }
    public void clearLog() { log.clear(); }
}
```

```java
// ─── File: src/test/java/com/bank/overview/FiveKeywordsTest.java ───
package com.bank.overview;

import com.bank.overview.service.TransferService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class FiveKeywordsTest {

    TransferService service = new TransferService();

    @BeforeEach void setup() { service.clearLog(); }

    // try + finally (success):
    @Test void tryAndFinally_onSuccess() throws Exception {
        String result = service.transfer("SAV2001", "CUR3001", new BigDecimal("5000"));
        assertThat(result).contains("Transfer");
        assertThat(service.getLog()).containsExactly("TRY: debit SAV2001", "TRY: credit CUR3001", "FINALLY: cleanup");
    }

    // try + catch + finally (exception):
    @Test void tryCatchFinally_onException() {
        assertThatThrownBy(() -> service.transfer("FROZEN", "CUR3001", new BigDecimal("5000")))
            .hasMessageContaining("frozen");
        assertThat(service.getLog()).containsExactly("TRY: debit FROZEN", "CATCH: Account frozen!", "FINALLY: cleanup");
    }

    // throw (raises exception):
    @Test void throw_raisesException() {
        assertThatThrownBy(() -> service.transfer("SAV2001", "CUR3001", new BigDecimal("-100")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("positive");
    }

    // throws (declares on signature):
    @Test void throws_declaresOnSignature() throws Exception {
        // Method signature: transfer(...) throws Exception
        // This test method MUST declare throws (or try-catch) because it calls transfer()
        String result = service.transfer("SAV2001", "CUR3001", new BigDecimal("1000"));
        assertThat(result).isNotNull();
    }

    // All 5 together:
    @Test void allFiveKeywords() {
        // try    → wraps code that might fail
        // catch  → handles the failure
        // finally → cleanup always runs
        // throw  → raises exception (IllegalArgumentException for negative amount)
        // throws → declares on method signature (tells caller to handle)
        assertThat(true).isTrue();
    }
}
